entries[233962] = { ["name"] = "Fläschchen des Wahnsinns", ["text"] = "Benötigt Stufe 60\nBenutzen: Erhöht 2 Stunden lang die Angriffskraft um 50. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
