entries[233987] = { ["name"] = "Generator für 6u73 5chw1n6un63n", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 60\nBenutzen: Entfaltet sich zu einem Generator für 6u73 5chw1n6un63n, der beschädigte Gegenstände reparieren kann und der Euch nicht benötigte Gegenstände abkauft. Nach 10 Min. versagt sein innerer Motor und er muss eine Weile ruhen. (4 Std. Abklingzeit)" }
entries[233988] = { ["name"] = "Gestimmte machtreaktive Scheibe", ["text"] = "Wird beim Anlegen gebunden\nSchildhand} Schild\n2822 Rüstung\n52 Blocken\n+20 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Verteidigung +7.\nAnlegen: Wenn der Schild blockt, löst er einen Elektroschock aus, der allen Gegnern in der Nähe Schaden zufügt. (1s Abklingzeit)\nBenutzen: Lädt die Energie des Schilds 3 Sek. lang auf, um allen Gegnern in der Nähe 450 bis 750 Naturschaden zuzufügen. Nach dem Einsatz benötigt der Schild 10 Sek. zum Wiederaufladen. (2 Min Abklingzeit)" }
