entries[234261] = { ["name"] = "Bauplan: Arkane Megabombe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (300)\nBenötigtZirkel des Cenarius\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung einer arkanen Megabombe.\nArkane Megabombe\nBenötigt Stufe 60\nBenutzen: Zieht 1075 bis 1525 Mana von allen ab, die sich im Sprengradius befinden und fügt dem Ziel Schaden in Höhe von 50% des abgezogenen Manas zu. Bringt die Ziele im Effektbereich außerdem 5 Sek. lang zum Schweigen. (1 Min Abklingzeit)\nBenötigt Empfindlicher Arkanitwandler , Nexuskristall , Runenstoff" }
