entries[235137] = { ["name"] = "Formel: Totem der donnernden Schläge", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch die Herstellung eines Totems der donnernden Schläge.\nTotem der donnernden Schläge\nWird beim Anlegen gebunden\nRelikt Totem\nBenötigt Stufe 60\nAnlegen: Erhöht den Schaden von 'Sturmschlag' und 'Waffe des Windzorns' um 3%.\nBenötigt Nexuskristall (3), Schwarmdistel (10), Obsidianangereicherter Thoriumbarren (2), Verzaubertes Leder (3)" }
entries[235138] = { ["name"] = "Formel: Totem des fließenden Magmas", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch die Herstellung eines Totems des fließenden Magmas.\nTotem des fließenden Magmas\nWird beim Anlegen gebunden\nRelikt Totem\nBenötigt Stufe 60\nAnlegen: Erhöht den Schaden von 'Flammenschock' und 'Schmelzschlag' um 3%.\nBenötigt Nexuskristall (3), Schwarmdistel (10), Obsidianangereicherter Thoriumbarren (2), Verzaubertes Leder (3)" }
entries[235139] = { ["name"] = "Formel: Götze des siderischen Zorns", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch die Herstellung eines Götzen des siderischen Zorns.\nGötze des siderischen Zorns\nWird beim Anlegen gebunden\nRelikt Götze\nBenötigt Stufe 60\nAnlegen: Erhöht den Schaden von 'Mondfeuer' und 'Zorn' um 3%.\nBenötigt Nexuskristall (2), Schwarmdistel (20), Verzaubertes Leder (3), Qirajipirschergift (4), Uralte Sandwurmgalle (4)" }
entries[235140] = { ["name"] = "Formel: Götze der Katzenwildheit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch die Herstellung eines Götzen der Katzenwildheit.\nGötze der Katzenwildheit\nWird beim Anlegen gebunden\nRelikt Götze\nBenötigt Stufe 60\nAnlegen: Erhöht den Schaden von 'Wilder Biss' und 'Schreddern' um 3%.\nBenötigt Nexuskristall (2), Schwarmdistel (20), Verzaubertes Leder (3), Qirajipirschergift (4), Uralte Sandwurmgalle (4)" }
entries[235141] = { ["name"] = "Formel: Götze der Bärenwut", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch die Herstellung eines Götzen der Bärenwut.\nGötze der Bärenwut\nWird beim Anlegen gebunden\nRelikt Götze\nBenötigt Stufe 60\nAnlegen: Erhöht den Schaden von 'Prankenhieb' und 'Zerfleischen' um 3%.\nBenötigt Nexuskristall (2), Schwarmdistel (20), Verzaubertes Leder (3), Qirajipirschergift (4), Uralte Sandwurmgalle (4)" }
entries[235142] = { ["name"] = "Blutbedeckte Silbermünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Transmutiert 100 blutbedeckte Silbermünzen zu einer blutbedeckten Goldmünze.\n\"Aus den Taschen Eurer Opfer geplündert und vom Blutloa gesegnet.\"" }
entries[235143] = { ["name"] = "Blutbedeckte Goldmünze", ["text"] = "Wird beim Aufheben gebunden\n\"Aus den Taschen Eurer Opfer geplündert und vom Blutloa gesegnet.\"" }
entries[235144] = { ["name"] = "Beutel mit blutbedeckten Kupfermünzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\n\"Enthält 100 blutbedeckte Kupfermünzen.\"\n<Zum Öffnen rechtsklicken>" }
entries[235145] = { ["name"] = "Beutel mit blutbedeckten Silbermünzen", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 100 blutbedeckte Silbermünzen.\"\n<Zum Öffnen rechtsklicken>" }
