entries[235282] = { ["name"] = "Fühler der Kräftigung", ["text"] = "Leerenberührt\nWird beim Aufheben gebunden\nDistanz Zauberstab\n107 - 199 Naturschaden Tempo 1.60\n(95.63 Schaden pro Sekunde)\n+4 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 31 und den verursachten Schaden um bis zu 11.\nAnlegen: Stellt alle 5 Sek. 2 Punkt(e) Mana wieder her." }
entries[235473] = { ["name"] = "Barrikade des Großmarschalls", ["text"] = "Wird beim Aufheben gebunden\nSchildhand} Schild\n3000 Rüstung\n56 Blocken\n+26 Ausdauer\n+10 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 44 Gesundheit und den verursachten Schaden um bis zu 24.\nAnlegen: Verringert den von Spielercharakteren und ihren Begleitern erlittenen Schaden um 5%. Dieser Effekt kann nicht aus mehreren Quellen kombiniert werden." }
entries[235474] = { ["name"] = "Barrikade des Obersten Kriegsfürsten", ["text"] = "Wird beim Aufheben gebunden\nSchildhand} Schild\n3000 Rüstung\n56 Blocken\n+26 Ausdauer\n+10 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 44 Gesundheit und den verursachten Schaden um bis zu 24.\nAnlegen: Verringert den von Spielercharakteren und ihren Begleitern erlittenen Schaden um 5%. Dieser Effekt kann nicht aus mehreren Quellen kombiniert werden." }
