entries[235481] = { ["name"] = "Hackbeil des Großmarschalls", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n89 - 134 Schaden Tempo 1.80\n(61.94 Schaden pro Sekunde)\n+13 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: +28 Angriffskraft.\nAnlegen: Verringert den von Spielercharakteren und ihren Begleitern erlittenen Schaden um 5%. Dieser Effekt kann nicht aus mehreren Quellen kombiniert werden." }
entries[235497] = { ["name"] = "Trunk der Sande", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenötigt Stufe 55\nBenutzen: Erhöht Zielen in Silithus, Ahn'Qiraj, den Östlichen Pestländern und Naxxramas zugefügten Schaden um 3% und den kritischen Schaden gegen Ziele in diesen Gebieten um zusätzliche 3%. (3 Sek. Abklingzeit)" }
entries[235511] = { ["name"] = "Makelloser gelber Qirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBenutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)" }
entries[235512] = { ["name"] = "Makelloser grüner Qirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBenutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)" }
entries[235513] = { ["name"] = "Makelloser blauer Qirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBenutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)" }
entries[235514] = { ["name"] = "Makelloser roter Qirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBenutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)" }
entries[235517] = { ["name"] = "Fackel", ["text"] = "Benötigt Stufe 60" }
entries[235526] = { ["name"] = "Formel: Armschiene - Zaubermacht", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nArmschienen dauerhaft so verzaubern, dass sie den Schaden von Zaubern um bis zu 12 erhöhen.\n\"Lehrt Euch, wie man Armschienen dauerhaft so verzaubert, dass sie den Schaden von Zaubern um bis zu 12 erhöhen.\"" }
entries[235528] = { ["name"] = "Formel: Armschiene - Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nArmschienen dauerhaft so verzaubern, dass sie die Beweglichkeit um 9 erhöhen.\n\"Lehrt Euch, wie man Armschienen dauerhaft so verzaubert, dass die Beweglichkeit um 9 erhöht wird.\"" }
entries[235529] = { ["name"] = "Obsidianzielfernrohr", ["text"] = "Benötigt Stufe 60\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit verursachten Schaden um 10." }
entries[235530] = { ["name"] = "Bauplan: Obsidianzielfernrohr", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (300)\n\"Lehrt Euch die Herstellung eines Obsidianzielfernrohrs.\"" }
entries[235597] = { ["name"] = "Zaubernotizen: Tieffrieren", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euren Helm mit der Rune 'Tieffrieren':\n\nBetäubt das Ziel für 5 Sek.. Funktioniert nur bei eingefrorenen Zielen. Fügt Zielen, die dauerhaft gegen Betäubungseffekte immun sind, [Quellwert] bis [Quellwert] Schaden zu. Dieser Schaden profitiert von 'Vergletscherung', braucht aber keine Stapel davon auf.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[235598] = { ["name"] = "Zaubernotizen: Eisige Adern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Eure Hosen mit der Rune 'Eisige Adern':\n\nBeschleunigt Euer Wirken von Zaubern, erhöht das Zaubertempo um 20% und verringert die Dauer der durch erlittenen Schaden verursachten Zauberzeiterhöhung beim Wirken von Zaubern um 100%. Hält 20 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[235599] = { ["name"] = "Zaubernotizen: Zeitanomalie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n{Prägt Euren Helm mit der Rune 'Zeitanomalie':\n\nSchleudert eine Kugel aus Temporalenergie, die sich langsam vorwärts bewegt und allen nahen Gruppenmitgliedern jede 2 Sek. einen Schild gewährt, der 15 Sek. lang [Quellwert] Schaden absorbiert. Dieser Schild häuft zusätzlichen Wert an, wenn Gruppenmitglieder in der Nähe der Kugel bleiben.}\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[235600] = { ["name"] = "Rune des göttlichen Sturms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euer Brustteil mit der Rune 'Göttlicher Sturm':\n\nEin sofortiger Waffenangriff, der bis zu 4 Gegnern innerhalb von 8 Metern 110% Waffenschaden zufügt. 'Göttlicher Sturm' heilt bis zu 3 Gruppen- oder Schlachtzugsmitglieder in Höhe von 25% des verursachten Schadens.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[235601] = { ["name"] = "Rune des Fanatismus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euren Helm mit der Rune 'Fanatismus':\n\nErhöht Eure kritische Trefferchance mit Heiligzaubern um 18%. Zudem heilen Eure kritischen Heilzauber das Ziel im Verlauf von 12 Sek. für 60% der geheilten Menge.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[235602] = { ["name"] = "Rune des Hammers der Rechtschaffenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Eure Armschienen mit der Rune 'Hammer der Rechtschaffenen':\n\nTrifft das aktuelle Ziel sowie bis zu 3 zusätzliche Ziele in der Nähe und verursacht pro Sekunde den 4-fachen Schaden Eurer Waffenhandwaffe als Heiligschaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[235603] = { ["name"] = "Rune der rechtschaffenen Vergeltung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euren Umhang mit der Rune 'Rechtschaffene Vergeltung':\n\nWenn Eure Zauber 'Richturteil', 'Kreuzfahrerstoß' oder 'Göttlicher Sturm' einen kritischen Treffer erzielen, erleidet Euer Ziel im Verlauf von bis Abbruch 30% zusätzlichen Schaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[235604] = { ["name"] = "Rune des Schilds der Rechtschaffenheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euren Umhang mit der Rune 'Schild der Rechtschaffenheit':\n\nVerpasst dem Ziel einen heftigen Schlag mit Eurem Schild, der Heiligschaden basierend auf Eurem Blockwert plus [Quellwert] verursacht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[235605] = { ["name"] = "Rune der schockierenden Ehrfurcht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euren Umhang mit der Rune 'Schockierende Ehrfurcht':\n\nWährend 'Zorn der Gerechtigkeit' nicht aktiv ist, erhaltet Ihr, wenn Ihr Schaden mit 'Heiliger Schock' verursacht, 1 Min. lang 200% Eurer Intelligenz als Zaubermacht. Zusätzlich verursacht Ihr 30% weniger Bedrohung.\n\nIhr erhaltet zudem 10 Sek. lang 'Sonnenlicht', wenn Ihr die Rune 'Lichtinfusion' geprägt habt.\n\n'Sonnenlicht' lässt Eure Fähigkeiten 'Göttlicher Sturm' und 'Kreuzfahrerstoß' sowie Eure Nahkampfangriffe zusätzlichen Heiligschaden in Höhe von 60% Eurer Heiligzaubermacht verursachen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[235785] = { ["name"] = "\"Schlüssel\" für Totenwindkäfig", ["text"] = "Questgegenstand\nEinzigartig\n\"Eure scharfsinnigen Observationsfähigkeiten stellen schnell fest, dass dieser \"Schlüssel\" lediglich ein Stein mit einer scharfen Kante ist. Ihr vermutet, dass es ausreichen sollte, ihn gegen das Schloss zu schlagen, um den Käfig zu öffnen.\"" }
entries[235786] = { ["name"] = "Karazhankuriosität", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (99)" }
entries[235787] = { ["name"] = "Uralter Eisenholzzweig", ["text"] = "Questgegenstand\nEinzigartig" }
entries[235788] = { ["name"] = "Enthusiastischer Irrwisch", ["text"] = "Questgegenstand\nEinzigartig\n\"Das Teil will einfach nicht stillhalten...\"" }
entries[235789] = { ["name"] = "Flamme des Lebens", ["text"] = "Questgegenstand\nEinzigartig" }
entries[235790] = { ["name"] = "Verzauberter Feuerbrand", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Haltet die verzauberte Fackel hoch und versucht, die Dunkelheit in den Karazhangruften zu vertreiben. (15 Sek. Abklingzeit)" }
entries[235825] = { ["name"] = "Trunk der Sande", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenötigt Stufe 55\nBenutzen: Erhöht Zielen in Silithus, Ahn'Qiraj, den Östlichen Pestländern und Naxxramas zugefügten Schaden um 2% und den kritischen Schaden gegen Ziele in diesen Gebieten um zusätzliche 2%. (3 Sek. Abklingzeit)" }
entries[235852] = { ["name"] = "Violettes Säckchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dieses kleine Säckchen trägt das Zeichen der Kirin Tor von Dalaran. Es scheint einige kleine Gegenstände zu enthalten, doch seltsamerweise scheint es Euch nicht möglich, es aufzumachen, um zu sehen, was sich darin befindet.\"" }
entries[235867] = { ["name"] = "Pergamentfetzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Der Pergamentfetzen scheint von einem größeren Poster oder Flugblatt abgerissen worden zu sein. Die einzigen Worte, die sich ausmachen lassen, scheinen ein Name zu sein... Erzmagier Tarsis Kir-Moldir\"" }
entries[235868] = { ["name"] = "Bollwerk des Zorns", ["text"] = "Wird beim Aufheben gebunden\nSchildhand} Schild\n3177 Rüstung\n61 Blocken\n+14 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Fügt Nahkampfangreifern 100 Schattenschaden zu. Erzeugt das Doppelte des verursachten Schadens an Bedrohung.\nAnlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 3%.\nAnlegen: Verteidigung +10." }
entries[235869] = { ["name"] = "Gugel des Meisters", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nKopf Leder\n198 Rüstung\n+10 Ausdauer\n+14 Intelligenz\n+10 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 59." }
entries[235870] = { ["name"] = "Kettenrasselnhelm", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nKopf Kette\n430 Rüstung\n+15 Beweglichkeit\n+10 Ausdauer\n+11 Intelligenz\n+9 Frostwiderstand\nHaltbarkeit 85 / 85\nBenötigt Stufe 60\nAnlegen: +100 Angriffskraft." }
entries[235871] = { ["name"] = "Klammernder Todeshelm", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nKopf Platte\n765 Rüstung\n+40 Stärke\n+25 Beweglichkeit\n+19 Ausdauer\n+12 Frostwiderstand\nHaltbarkeit 100 / 100\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%." }
