entries[235891] = { ["name"] = "Die gute Alte", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n290 - 355 Schaden Tempo 3.80\n(84.87 Schaden pro Sekunde)\n+50 Stärke\n+12 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nBenutzen: Zerschmettert die Leiche eines gefallenen Freundes oder Gegners und fügt Gegnern in der Nähe 588 Schaden zu. (2 Min Abklingzeit)\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n\"Garantiert, das kein Grab zweimal gegraben werden muss.\"" }
