entries[235893] = { ["name"] = "Schattengebundenes Grimoire", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+11 Intelligenz\nBenötigt Stufe 60\nAnlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 43.\n\nKharons Erlass (0/2)\nSchattengebundenes Grimoire\nNiedergang des Verdammnisverkünders\n(2) Set : Der verursachte Schaden von 'Schleichende Dunkelheit' wird um 100% erhöht." }
entries[235894] = { ["name"] = "Niedergang des Verdammnisverkünders", ["text"] = "Wird beim Aufheben gebunden\nDistanz Zauberstab\n153 - 188 Schattenschaden Tempo 1.50\n(113.67 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Regelmäßige Schatteneffekte haben eine Chance, bis zu 5-mal 'Schleichende Dunkelheit' anzuwenden. Zauber, die direkten Schattenschaden verursachen, lassen diesen Effekt detonieren und verursachen 100 Schaden pro Stapel. (1.5s Abklingzeit)\n\nKharons Erlass (0/2)\nSchattengebundenes Grimoire\nNiedergang des Verdammnisverkünders\n(2) Set : Der verursachte Schaden von 'Schleichende Dunkelheit' wird um 100% erhöht." }
