entries[236398] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n130 - 243 Schaden Tempo 2.90\n(64.31 Schaden pro Sekunde)\n+20 Ausdauer\n+14 Intelligenz\n+30 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Hexenmeister\nBenötigt Stufe 60\nAnlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 150.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung aller Gruppenmitglieder innerhalb von 30 Metern um bis zu 33. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar.\nBenutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)" }
entries[236399] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n130 - 243 Schaden Tempo 2.90\n(64.31 Schaden pro Sekunde)\n+20 Ausdauer\n+22 Intelligenz\n+24 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Priester\nBenötigt Stufe 60\nAnlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\nAnlegen: Erhöht für alle Gruppenmitglieder innerhalb von 30 Metern durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 62 Gesundheit und den verursachten Schaden um bis zu 19. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 300 Gesundheit und den verursachten Schaden um bis zu 150.\nBenutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)" }
entries[236400] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n129 - 242 Schaden Tempo 2.90\n(63.97 Schaden pro Sekunde)\n+21 Ausdauer\n+24 Intelligenz\n+23 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Magier\nBenötigt Stufe 60\nAnlegen: Erhöht Euer Zaubertempo um 4%.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 150.\nAnlegen: Erhöht das Zaubertempo aller Gruppenmitglieder innerhalb von 30 Metern um 2%. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar.\nBenutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)" }
entries[236401] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n129 - 242 Schaden Tempo 2.90\n(63.97 Schaden pro Sekunde)\n+21 Ausdauer\n+25 Intelligenz\n+20 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Druide\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 3%.\nAnlegen: Erhöht die kritische Zaubertrefferchance aller Gruppenmitglieder innerhalb von 30 Metern um 2%. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 300 Gesundheit und den verursachten Schaden um bis zu 150.\nAnlegen: +592 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\nBenutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)" }
entries[236414] = { ["name"] = "Beschädigte Vorratskiste aus Undermine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\n\"Diese verbeulte und beschädigte Kiste sieht aus, als wäre sie buchstäblich von einem Zeppelin gefallen.\"\n<Zum Öffnen rechtsklicken>" }
entries[236417] = { ["name"] = "Seele des Taktikers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\nBenutzen: Die Seele des Taktikers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nNachdem Ihr die Haltung wechselt, sind die Wutkosten Eurer nächsten Offensivfähigkeit um 10 verringert." }
entries[236418] = { ["name"] = "Seele des Kriegsveteranen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\nBenutzen: Die Seele des Kriegsveteranen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nNach Verlassen einer Haltung könnt Ihr 15 Sek. lang noch Fähigkeiten nutzen, die diese Haltung erfordern." }
entries[236419] = { ["name"] = "Seele des Kampfvoraussehers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nKlassen: Krieger\nBenötigt Stufe 55\nBenutzen: Die Seele des Kampfvoraussehers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr eine Haltung einnehmt, erhaltet Ihr für 15 Sek. einen weiteren Vorteil:\n\nKampfhaltung/Gladiatorhaltung: Verursachter Schaden um 5% erhöht.\n\nBerserkerhaltung: Kritische Trefferchance um 5% erhöht.\n\nVerteidigungshaltung: Erlittener körperlicher Schaden um 5% verringert." }
